1086			for _, l := range iv.Landmarks {
1087				if l.ID == "" || l.Occurrence < 1 {
1088					return fmt.Errorf("%w: invalid invalidation landmark entry", ErrCorrupt)
1089				}
1090				if _, dup := lmSeen[l.ID]; dup {
1091					return fmt.Errorf("%w: invalidation %s lists %s twice", ErrCorrupt, iv.ID, l.ID)
1092				}
1093				lmSeen[l.ID] = struct{}{}
1094			}
1095			// 交叉核对：成功失效结果里的每个（路标标识，出现编号）必须准确
1096			// 指向该路标历史中同编号的那次出现，不能改指同一路标的其他出现，
1097			// 也不能因为路标后来再次出现就把旧结果指向最新记录。被指出现必须
1098			// 已经失效，且其上记录的失效操作标识、失效时间、失效原因都与这条
1099			// 操作记录一致——时间与原因各自再合理也不够，实际由另一条操作撤下
1100			// 时不能仅凭相同时间/原因认可。旧版平铺路标视为第 1 次有效出现，
1101			// 不可能被失效记录引用（引用即损坏）。一条操作同时撤下多个路标时，
1102			// 任意一个条目不满足对应关系都拒绝打开整个文件。
1103			for _, l := range iv.Landmarks {
1104				lm := lmByID[l.ID]
1105				if lm == nil {
1106					return fmt.Errorf("%w: invalidation %s result points to unknown landmark %s", ErrCorrupt, iv.ID, l.ID)
1107				}
1108				if len(lm.Occurrences) == 0 {
1109					return fmt.Errorf("%w: invalidation %s result points to flat legacy landmark %s which has no invalidated occurrence", ErrCorrupt, iv.ID, l.ID)
1110				}
1111				if l.Occurrence > len(lm.Occurrences) {
1112					return fmt.Errorf("%w: invalidation %s result points to landmark %s occurrence %d which does not exist", ErrCorrupt, iv.ID, l.ID, l.Occurrence)
1113				}
1114				// 出现编号连续性已在上方路标校验中强制，该下标处编号即 l.Occurrence。
1115				oj := lm.Occurrences[l.Occurrence-1]
1116				if oj.Active {
1117					return fmt.Errorf("%w: invalidation %s result points to landmark %s occurrence %d which is still active", ErrCorrupt, iv.ID, l.ID, l.Occurrence)
1118				}
1119				if oj.InvalidOpID != iv.ID || oj.InvalidTime != iv.Time || oj.InvalidReason != iv.Reason {
1120					return fmt.Errorf("%w: invalidation %s result for landmark %s occurrence %d does not match its saved invalidation (op %q, time %d, reason %q)", ErrCorrupt, iv.ID, l.ID, l.Occurrence, oj.InvalidOpID, oj.InvalidTime, oj.InvalidReason)
1121				}
1122				invalTriples[invalTriple{op: iv.ID, lm: l.ID, num: l.Occurrence}] = struct{}{}
1123			}
1124		}
1125		// 反向核对：每个已失效出现都必须能在失效操作序列中找到引用同一（操作，
1126		// 路标，出现编号）三元组的条目。正向核对已保证被引用出现的失效时间与
1127		// 原因和引用方一致；此处堵住另一方向的矛盾：出现凭空携带失效信息、
1128		// 声称撤下它的操作记录实际指向另一次出现，或两次出现声称被同一操作
1129		// 撤下（一次操作对同一路标只会撤下当时唯一的有效出现）。旧地图没有
1130		// 失效操作时，平铺路标视为有效、不携带失效信息，不会触发；旧地图后来
1131		// 产生的失效操作同样在上述核对之列，不要求补齐原本缺失的逐帧观测。
1132		for _, lm := range fd.Landmarks {
1133			for _, oj := range lm.Occurrences {
1134				if oj.Active {
1135					continue
1136				}
1137				if _, ok := invalTriples[invalTriple{op: oj.InvalidOpID, lm: lm.ID, num: oj.Number}]; !ok {
1138					return fmt.Errorf("%w: landmark %s occurrence %d is marked invalidated by operation %q which does not record that invalidation", ErrCorrupt, lm.ID, oj.Number, oj.InvalidOpID)
1139				}
1140			}
1141		}
1142		return nil
1143	}
1144	
1145	func finitePose(p Pose) bool {
1146		return isFinite(p.X) && isFinite(p.Y) && isFinite(p.Heading) && isFinite(p.Variance)
1147	}
1148	
1149	// geomTol 是打开时核对校正记录几何一致性的相对容差（另含 1 的绝对项）。
1150	const geomTol = 1e-9
1151	
1152	// coordClose 判断保存坐标 got 是否在容许误差内等于期望 want：误差不得
1153	// 超过 geomTol 乘以 1、|want|、|got| 三者中的最大值。参与比较的值都已
1154	// 校验为有限，差值必有限，NaN 不会混入并被误当相等。
1155	func coordClose(got, want float64) bool {
1156		scale := math.Max(1, math.Max(math.Abs(want), math.Abs(got)))
1157		return math.Abs(got-want) <= geomTol*scale
1158	}
1159	
1160	// angleClose 按最短角度差判断两个角度是否相等，容差 geomTol 弧度。两个
1161	// 角度都已校验为有限；差值经归一化到 [-π,π) 即最短角度差，正确处理
1162	// ±π 附近跨边界但物理方向相同的情形。
1163	func angleClose(got, want float64) bool {
1164		return math.Abs(normalizeAngle(got-want)) <= geomTol
1165	}
1166	
1167	// canonicalCorrectionHash 计算一次校正请求（锚点时间 + 目标位姿）的
1168	// 确定性指纹，用于同标识重复提交判定。直接按 IEEE-754 位编码。
1169	func canonicalCorrectionHash(anchor int64, tgt CorrectionTarget) string {
1170		h := sha256.New()
1171		var b [8]byte
1172		binary.BigEndian.PutUint64(b[:], uint64(anchor))
1173		h.Write(b[:])
1174		for _, v := range []float64{tgt.X, tgt.Y, tgt.Heading, tgt.Variance} {
1175			binary.BigEndian.PutUint64(b[:], math.Float64bits(v))
1176			h.Write(b[:])
1177		}
1178		return fmt.Sprintf("%x", h.Sum(nil))
1179	}
1180	
1181	// saveExclusive 创建新文件，目标已存在即失败（O_EXCL）。
1182	func (m *Map) saveExclusive() error {
1183		data, err := encodeFile(m.state)
1184		if err != nil {
1185			return err
1186		}
1187		f, err := os.OpenFile(m.path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o644)
1188		if err != nil {
1189			return err
1190		}
1191		return writeAndClose(f, data, m.path)
1192	}
1193	
1194	// saveReplace 用同目录临时文件 + rename 原子替换现有文件。
1195	func (m *Map) saveReplace() (err error) {
1196		data, err := encodeFile(m.state)
1197		if err != nil {
1198			return err
1199		}
1200		dir, base := filepath.Split(m.path)
1201		if dir == "" {
1202			dir = "."
1203		}
1204		f, err := os.CreateTemp(dir, base+".tmp-*")
1205		if err != nil {
1206			return err
1207		}
1208		tmpName := f.Name()
1209		// 任何失败路径都尽力清理临时文件。
1210		defer func() {
1211			if err != nil {
1212				_ = os.Remove(tmpName)
1213			}
1214		}()
1215		if err = writeAndClose(f, data, tmpName); err != nil {
1216			return err
1217		}
1218		if err = os.Rename(tmpName, m.path); err != nil {
1219			return err
1220		}
1221		return nil
1222	}
1223	
1224	func writeAndClose(f *os.File, data []byte, name string) (err error) {
1225		defer func() {
1226			if cerr := f.Close(); err == nil {
1227				err = cerr
1228			}
1229		}()
1230		if _, err = f.Write(data); err != nil {
1231			return err
1232		}
1233		if err = f.Sync(); err != nil {
1234			return err
1235		}
1236		return nil
1237	}
1238	
1239	// canonicalHash 计算一批帧的确定性指纹，用于重复导入判定。直接按
1240	// IEEE-754 位编码，NaN/Inf 也有稳定表示，不依赖 JSON 对其不支持的问题。
1241	func canonicalHash(frames []Frame) string {
1242		h := sha256.New()
1243		var lenBuf [4]byte
1244		var numBuf [8]byte
1245		putU32 := func(v uint32) {
1246			binary.BigEndian.PutUint32(lenBuf[:], v)
1247			h.Write(lenBuf[:])
1248		}
1249		putU64 := func(v uint64) {
1250			binary.BigEndian.PutUint64(numBuf[:], v)
1251			h.Write(numBuf[:])
1252		}
1253		putStr := func(s string) {
1254			putU32(uint32(len(s)))
1255			h.Write([]byte(s))
1256		}
1257	
1258		putU32(uint32(len(frames)))
1259		for _, fr := range frames {
1260			putU64(uint64(fr.Time))
1261			putU64(math.Float64bits(fr.DX))
1262			putU64(math.Float64bits(fr.DY))
1263			putU64(math.Float64bits(fr.DHeading))
1264			putU64(math.Float64bits(fr.MoveVariance))
1265			putU32(uint32(len(fr.Observations)))
1266			for _, ob := range fr.Observations {
1267				putStr(ob.ID)
1268				putU64(math.Float64bits(ob.X))
1269				putU64(math.Float64bits(ob.Y))
1270			}
1271		}
1272		return fmt.Sprintf("%x", h.Sum(nil))
1273	}
1274

