118	
119		// 路标查询结果与校正记录中的新位置一致。
120		lms, _ = m.LandmarksInRect(Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9})
121		if len(lms) != 1 || lms[0].ID != "L" {
122			t.Fatalf("landmarks after = %v", lms)
123		}
124		approxEq(t, "queried L x", lms[0].X, lc.After.X)
125		approxEq(t, "queried L y", lms[0].Y, lc.After.Y)
126		if lms[0].Count != lc.After.Count {
127			t.Fatalf("queried count = %d, record count = %d", lms[0].Count, lc.After.Count)
128		}
129	
130		// 历次出现：仍只有第 1 次出现、仍有效，位置/计数与记录一致，首次
131		// 观测时间为锚点之前的 50。
132		h, err := m.LandmarkAppearances("L")
133		if err != nil {
134			t.Fatal(err)
135		}
136		if len(h.Appearances) != 1 {
137			t.Fatalf("appearances = %+v", h.Appearances)
138		}
139		ap := h.Appearances[0]
140		if ap.Number != 1 || !ap.Active || ap.FirstSeenTime != 50 || !ap.HasFirstSeen {
141			t.Fatalf("appearance = %+v", ap)
142		}
143		approxEq(t, "appearance L x", ap.Landmark.X, lc.After.X)
144		if ap.Landmark.Count != 5 {
145			t.Fatalf("appearance count = %d, want 5", ap.Landmark.Count)
146		}
147	
148		// 更早的位姿（初始位姿 t=0 与锚点前一帧 t=50）不变；锚点及之后采用
149		// 校正后位姿。
150		checkPose := func(time int64, wantX float64) Pose {
151			t.Helper()
152			p, err := m.PoseAt(time)
153			if err != nil {
154				t.Fatalf("PoseAt(%d): %v", time, err)
155			}
156			if p.X != wantX || p.Heading != 0 {
157				t.Fatalf("PoseAt(%d) = %+v, want X=%v heading=0", time, p, wantX)
158			}
159			return p
160		}
161		p50 := checkPose(50, 0)
162		approxEq(t, "t=50 variance unchanged", p50.Variance, 0.6) // 初始 0.5 + 0.1
163		p0 := checkPose(0, 0)
164		approxEq(t, "initial variance unchanged", p0.Variance, 0.5)
165		p100, _ := m.PoseAt(100)
166		approxEq(t, "anchor x after", p100.X, -0.5)
167		approxEq(t, "anchor heading after", p100.Heading, 0)
168		// 锚点后方差 = 目标方差 0 + 锚点后运动方差 0.1（t=200）；t=100 为目标方差。
169		approxEq(t, "anchor variance after", p100.Variance, 0)
170		p200, _ := m.PoseAt(200)
171		approxEq(t, "t=200 x after", p200.X, -0.5)
172		approxEq(t, "t=200 variance after", p200.Variance, 0.1)
173	
174		// 既有校正记录只增不改：记录保留校正前后位置与不变的次数。
175		recs, _ := m.Corrections()
176		if len(recs) != 1 || !recordsEqual(recs[0], rec) {
177			t.Fatalf("records = %+v, want %+v", recs, rec)
178		}
179	}
180	
181	// 输入次序确实影响校正接纳结果，而不只是影响最终均值：同一份观测点
182	// 集合，按次序 A 导入的地图上提交平移 -0.5 的位置校正全部接纳成功；
183	// 另一个独立地图以次序 B 成功导入这些点后，提交完全相同的校正，却在
184	// 锚点帧第二条同帧观测处超过合并距离被拒。两份原轨迹都合法，差别只
185	// 来自校正后的逐条接纳过程。
186	func TestCorrectionSameFrameOrderDeterminesAcceptance(t *testing.T) {
187		req := Correction{
188			ID:     "c-order",
189			Anchor: 100,
190			Target: CorrectionTarget{X: -0.5, Y: 0, Heading: 0, Variance: 0},
191		}
192	
193		// 地图 A：次序 A，同样的校正成功。
194		mA := newMap(t, sameFrameConfig())
195		if _, err := mA.ImportSegment(sameFrameLGeometry(true)); err != nil {
196			t.Fatalf("import A: %v", err)
197		}
198		recA, err := mA.Correct(req)
199		if err != nil {
200			t.Fatalf("correction on order A rejected: %v", err)
201		}
202		approxEq(t, "A L after x", recA.Landmarks[0].After.X, -0.6)
203		if recA.Landmarks[0].After.Count != 5 {
204			t.Fatalf("A count = %d, want 5", recA.Landmarks[0].After.Count)
205		}
206	
207		// 地图 B：独立文件，次序 B 成功导入（原轨迹合法）。
208		mB := newMap(t, sameFrameConfig())
209		if _, err := mB.ImportSegment(sameFrameLGeometry(false)); err != nil {
210			t.Fatalf("import B: %v", err)
211		}
212		// 导入后两个地图的路标状态相同：同一观测点集合的等权平均与次数。
213		bBefore, _ := mB.LandmarksInRect(Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9})
214		if len(bBefore) != 1 {
215			t.Fatalf("B landmarks = %v", bBefore)
216		}
217		approxEq(t, "B L x before", bBefore[0].X, -0.2)
218		if bBefore[0].Count != 5 {
219			t.Fatalf("B count before = %d, want 5", bBefore[0].Count)
220		}
221		// 提交同样的校正：锚点帧第二条同帧观测与接纳第一条后的新均值相距
222		// 1.25 > 合并上限 1 → 整次拒绝。
223		_, err = mB.Correct(req)
224		r, ok := AsRejectError(err)
225		if !ok {
226			t.Fatalf("B correction err = %v, want *RejectError", err)
227		}
228		if r.Kind != RejectLandmarkConflict {
229			t.Fatalf("B correction kind = %q, want %q", r.Kind, RejectLandmarkConflict)
230		}
231		// 错误指出实际冲突帧时间、路标标识及所属出现编号。
232		if !r.HasTime || r.Time != 100 || !r.HasLandmark || r.Landmark != "L" ||
233			!r.HasOccurrence || r.Occurrence != 1 {
234			t.Fatalf("B reject = %+v, want time=100 landmark=L occurrence=1", r)
235		}
236	
237		// B 整次校正不生效：路标位置/次数、位姿、校正记录均为提交前结果。
238		assertUnchangedAfterRejectedOrderB(t, mB)
239	}
240	
241	// assertUnchangedAfterRejectedOrderB 校验次序 B 地图在校正被整体拒绝后
242	// 没有任何部分更新：同帧前一条已暂时接纳的观测没有改变路标位置或次数，
243	// 位姿与既有校正记录也保持提交前结果。
244	func assertUnchangedAfterRejectedOrderB(t *testing.T, m *Map) {
245		t.Helper()
246		lms, _ := m.LandmarksInRect(Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9})
247		if len(lms) != 1 || lms[0].ID != "L" {
248			t.Fatalf("landmarks after reject = %v", lms)
249		}
250		approxEq(t, "L x unchanged", lms[0].X, -0.2)
251		approxEq(t, "L y unchanged", lms[0].Y, 0)
252		if lms[0].Count != 5 {
253			t.Fatalf("L count after reject = %d, want 5 (tentative admission leaked)", lms[0].Count)
254		}
255		h, err := m.LandmarkAppearances("L")
256		if err != nil {
257			t.Fatal(err)
258		}
259		if len(h.Appearances) != 1 || !h.Appearances[0].Active {
260			t.Fatalf("appearances after reject = %+v", h.Appearances)
261		}
262		approxEq(t, "appearance x unchanged", h.Appearances[0].Landmark.X, -0.2)
263		if h.Appearances[0].Landmark.Count != 5 {
264			t.Fatalf("appearance count after reject = %d", h.Appearances[0].Landmark.Count)
265		}
266		for _, tc := range []struct {
267			time         int64
268			wantX        float64
269			wantHeading  float64
270			wantVariance float64
271		}{
272			{0, 0, 0, 0.5},
273			{50, 0, 0, 0.6},
274			{100, 0, 0, 0.7},
275			{200, 0, 0, 0.8},
276		} {
277			p, err := m.PoseAt(tc.time)
278			if err != nil {
279				t.Fatalf("PoseAt(%d): %v", tc.time, err)
280			}
281			if p.X != tc.wantX || p.Heading != tc.wantHeading || math.Abs(p.Variance-tc.wantVariance) > 1e-12 {
282				t.Fatalf("PoseAt(%d) = %+v, want X=%v heading=%v variance=%v",
283					tc.time, p, tc.wantX, tc.wantHeading, tc.wantVariance)
284			}
285		}
286		// 同标识校正可再次提交（冲突的那次没有消耗校正标识、没有落记录）。
287		if recs, _ := m.Corrections(); len(recs) != 0 {
288			t.Fatalf("correction records after reject = %v, want none", recs)
289		}
290	}
291	
292	// 同帧内前一条已被接纳、后一条才发生冲突：冲突观测之前的同帧第一条
293	// 观测（与固定观测距离恰好等于合并上限）已在暂存聚合中接纳，但整次
294	// 校正仍必须失败且不留任何部分更新。错误指出实际冲突帧时间、路标
295	// 标识与所属出现编号。
296	func TestCorrectionSameFrameConflictAfterTentativeAdmission(t *testing.T) {
297		cfg := sameFrameConfig()
298		m := newMap(t, cfg)
299		// t=50：对 L 的固定观测，世界 X=0。
300		// t=100：同帧两条 L 观测，本地 X 依次为 0、+1（导入时世界 X 为
301		// 0、+1：第一条与固定观测重合，第二条距当时均值 0.5 恰在限内，
302		// 两条都合法）。
303		if _, err := m.ImportSegment(Segment{
304			ID: "seg",
305			Frames: []Frame{
306				{Time: 50, DX: 0, MoveVariance: 0.1,
307					Observations: []Observation{{ID: "L", X: 0, Y: 0}}},
308				{Time: 100, DX: 0, MoveVariance: 0.1,
309					Observations: []Observation{{ID: "L", X: 0, Y: 0}, {ID: "L", X: 1, Y: 0}}},
310			},
311		}); err != nil {
312			t.Fatalf("import: %v", err)
313		}
314		// 校正前 L 为 (0,0,+1)/3 即 X=1/3，计数 3。
315		lms, _ := m.LandmarksInRect(Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9})
316		if len(lms) != 1 {
317			t.Fatalf("landmarks = %v", lms)
318		}
319		approxEq(t, "L x before", lms[0].X, 1.0/3.0)
320		if lms[0].Count != 3 {
321			t.Fatalf("L count before = %d, want 3", lms[0].Count)
322		}
323	
324		// 只平移不旋转 +1：锚点帧第一条世界 X=1，与固定观测 0 的距离恰好
325		// 等于合并上限 1 → 暂纳（均值变为 0.5、计数 2）；第二条世界 X=2，
326		// 与新均值 0.5 相距 1.5 > 1 → 冲突。
327		_, err := m.Correct(Correction{
328			ID:     "c-conflict",
329			Anchor: 100,
330			Target: CorrectionTarget{X: 1, Y: 0, Heading: 0, Variance: 0},
331		})
332		r, ok := AsRejectError(err)
333		if !ok {
334			t.Fatalf("err = %v, want *RejectError", err)
335		}
336		if r.Kind != RejectLandmarkConflict || !r.HasTime || r.Time != 100 ||
337			!r.HasLandmark || r.Landmark != "L" || !r.HasOccurrence || r.Occurrence != 1 {
338			t.Fatalf("reject = %+v, want landmark_conflict at time 100 L occurrence 1", r)
339		}
340	
341		// 整次校正不生效：第一条已暂纳的观测没有改变路标位置或次数。
342		lms, _ = m.LandmarksInRect(Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9})
343		if len(lms) != 1 {
344			t.Fatalf("landmarks after conflict = %v", lms)
345		}
346		approxEq(t, "L x after conflict", lms[0].X, 1.0/3.0)
347		if lms[0].Count != 3 {
348			t.Fatalf("L count after conflict = %d, want 3 (tentative admission leaked)", lms[0].Count)
349		}
350		h, _ := m.LandmarkAppearances("L")
351		if len(h.Appearances) != 1 || !h.Appearances[0].Active {
352			t.Fatalf("appearances after conflict = %+v", h.Appearances)
353		}
354		approxEq(t, "appearance x after conflict", h.Appearances[0].Landmark.X, 1.0/3.0)
355		if h.Appearances[0].Landmark.Count != 3 {
356			t.Fatalf("appearance count after conflict = %d", h.Appearances[0].Landmark.Count)
357		}
358		// 位姿保持提交前结果。
359		cur, _ := m.CurrentPose()
360		if cur.Time != 100 || cur.X != 0 || cur.Heading != 0 {
361			t.Fatalf("current pose after conflict = %+v", cur)
362		}
363		approxEq(t, "current variance after conflict", cur.Variance, 0.7)
364		// 既有校正记录保持提交前结果（无记录）。
365		if recs, _ := m.Corrections(); len(recs) != 0 {
366			t.Fatalf("correction records after conflict = %v, want none", recs)
367		}
368	
369		// 同一张图把平移改成恰好可接纳（0 平移的恒等位置校正）后可成功，
370		// 证明被拒完全源于同帧逐条次序而非观测或轨迹本身。
371		rec, err := m.Correct(Correction{
372			ID:     "c-conflict",
373			Anchor: 100,
374			Target: CorrectionTarget{X: 0, Y: 0, Heading: 0, Variance: 0},
375		})
376		if err != nil {
377			t.Fatalf("identity correction after conflict: %v", err)
378		}
379		if len(rec.Landmarks) != 1 || rec.Landmarks[0].After.Count != 3 {
380			t.Fatalf("identity record = %+v", rec.Landmarks)
381		}
382		approxEq(t, "L x after identity", rec.Landmarks[0].After.X, 1.0/3.0)
383	}
384

