169			wantOpen bool
170		}{
171			{"within half tolerance", 4e-9, true},
172			{"beyond tolerance", 2e-8, false},
173		}
174		for _, tc := range coordCases {
175			t.Run("coord "+tc.name, func(t *testing.T) {
176				path := filepath.Join(t.TempDir(), "m.pose")
177				buildOverlappingCorrectionsMap(t, path, 10)
178				saved := 9.0 + tc.perturb
179				tamperFile(t, path, func(fd *fileData) {
180					fd.Trajectory[2].X = saved // t=200 期望 9
181				})
182				if !tc.wantOpen {
183					assertOpenCorrupt(t, path)
184					return
185				}
186				m, err := Open(path)
187				if err != nil {
188					t.Fatalf("within tolerance should open: %v", err)
189				}
190				p, _ := m.PoseAt(200)
191				if p.X != saved {
192					t.Fatalf("query x = %v, want saved value %v", p.X, saved)
193				}
194				recs, _ := m.Corrections()
195				if recs[1].Poses[0].After.X != 9 {
196					t.Fatalf("record after x = %v, want original 9", recs[1].Poses[0].After.X)
197				}
198				m.Close()
199			})
200		}
201	
202		angleCases := []struct {
203			name     string
204			perturb  float64
205			wantOpen bool
206		}{
207			{"within half tolerance", 5e-10, true},
208			{"beyond tolerance", 2e-9, false},
209		}
210		for _, tc := range angleCases {
211			t.Run("angle "+tc.name, func(t *testing.T) {
212				path := filepath.Join(t.TempDir(), "m.pose")
213				buildOverlappingCorrectionsMap(t, path, 10)
214				tamperFile(t, path, func(fd *fileData) {
215					fd.Trajectory[4].Heading = tc.perturb // t=400 期望 0
216				})
217				if tc.wantOpen {
218					m, err := Open(path)
219					if err != nil {
220						t.Fatalf("within angle tolerance should open: %v", err)
221					}
222					p, _ := m.PoseAt(400)
223					if p.Heading != tc.perturb {
224						t.Fatalf("query heading = %v, want saved %v", p.Heading, tc.perturb)
225					}
226					m.Close()
227				} else {
228					assertOpenCorrupt(t, path)
229				}
230			})
231		}
232	
233		t.Run("variance must match exactly", func(t *testing.T) {
234			path := filepath.Join(t.TempDir(), "m.pose")
235			buildOverlappingCorrectionsMap(t, path, 10)
236			tamperFile(t, path, func(fd *fileData) {
237				fd.Trajectory[2].Variance = 2 + 1e-12 // 期望恰为 2
238			})
239			assertOpenCorrupt(t, path)
240		})
241	}
242	
243	// 路标合并距离再大也不能放宽最后一次校正结果的核对：偏差 0.5 远小于
244	// 1e9 的合并距离，仍按损坏拒绝。
245	func TestOpenLastCorrectionRejectedRegardlessOfMergeDistance(t *testing.T) {
246		path := filepath.Join(t.TempDir(), "m.pose")
247		buildOverlappingCorrectionsMap(t, path, 1e9)
248		tamperFile(t, path, func(fd *fileData) {
249			fd.Trajectory[3].X = 10.5 // t=300 期望 10，偏差 0.5 << 合并距离 1e9
250		})
251		assertOpenCorrupt(t, path)
252	}
253	
254	// 后来追加、不属于任何校正记录的帧不参与这项核对：c2 结束于 400，之后
255	// 追加的 500、600 不属于 c1/c2，篡改非段末帧 500 的保存位姿仍可打开，
256	// 查询返回文件原值。
257	func TestOpenDoesNotRequireFramesOutsideCorrections(t *testing.T) {
258		path := filepath.Join(t.TempDir(), "m.pose")
259		buildOverlappingCorrectionsMap(t, path, 10)
260		m, err := Open(path)
261		if err != nil {
262			t.Fatal(err)
263		}
264		// 一次导入两帧：500 不是段末帧（段末为 600），段末位姿核对不涉及它，
265		// 隔离出新核对本身对“范围外帧”的态度。
266		if _, err := m.ImportSegment(Segment{ID: "s3", Frames: []Frame{
267			{Time: 500, DX: 1, MoveVariance: 0.1},
268			{Time: 600, DX: 1, MoveVariance: 0.1},
269		}}); err != nil {
270			t.Fatal(err)
271		}
272		if err := m.Close(); err != nil {
273			t.Fatal(err)
274		}
275		tamperFile(t, path, func(fd *fileData) {
276			if fd.Trajectory[5].Time != 500 {
277				t.Fatalf("setup: %+v", fd.Trajectory)
278			}
279			fd.Trajectory[5].X = 424242
280		})
281		m2, err := Open(path)
282		if err != nil {
283			t.Fatalf("frames outside all corrections must not be checked: %v", err)
284		}
285		p, _ := m2.PoseAt(500)
286		if p.X != 424242 {
287			t.Fatalf("PoseAt(500) = %+v, want saved value 424242", p)
288		}
289		m2.Close()
290	}
291	
292	// 兼容规则：帧的最后一条覆盖记录范围内含缺少逐帧依据的 null 旧帧时，
293	// 跳过该帧与当前轨迹的比较——即使当前位姿被改成明显矛盾值也放行；同一
294	// 文件中另一条依据完整、作为某些帧最后一次校正的记录仍须核对。
295	func TestOpenSkipsLastCorrectionCheckForNullBasis(t *testing.T) {
296		path := filepath.Join(t.TempDir(), "m.pose")
297		m, err := Create(path, Config{
298			InitialTime: 0, MaxInterval: 1000, MergeDistance: 10,
299		})
300		if err != nil {
301			t.Fatal(err)
302		}
303		if _, err := m.ImportSegment(Segment{ID: "s1", Frames: []Frame{
304			{Time: 100, DX: 1, MoveVariance: 0.1},
305			{Time: 200, DX: 1, MoveVariance: 0.1},
306			{Time: 300, DX: 1, MoveVariance: 0.1},
307		}}); err != nil {
308			t.Fatal(err)
309		}
310		if _, err := m.Correct(Correction{ID: "c1", Anchor: 100,
311			Target: CorrectionTarget{X: 5, Y: 6, Variance: 1}}); err != nil {
312			t.Fatal(err)
313		}
314		if err := m.Close(); err != nil {
315			t.Fatal(err)
316		}
317	
318		// t=200 的逐帧依据置空：c1 范围 100~300 含 null 旧帧，并把当前轨迹
319		// 改成任意矛盾值——锚点 100、中间帧 200、结束帧 300 全部跳过核对。
320		tamperFile(t, path, func(fd *fileData) {
321			fd.Sources[1] = nil
322			fd.Trajectory[1].X = 500
323			fd.Trajectory[2].X = 500
324			fd.Trajectory[3].X = 500
325		})
326		m2, err := Open(path)
327		if err != nil {
328			t.Fatalf("frames whose last correction spans a null basis frame keep legacy rules: %v", err)
329		}
330	
331		// 追加依据完整的新帧，并只对该帧提交一帧校正（范围不含 null 帧）。
332		if _, err := m2.ImportSegment(Segment{ID: "s2", Frames: []Frame{
333			{Time: 400, DX: 1, MoveVariance: 0.1},
334		}}); err != nil {
335			t.Fatal(err)
336		}
337		if _, err := m2.Correct(Correction{ID: "c2", Anchor: 400,
338			Target: CorrectionTarget{X: 9, Y: 9, Variance: 2}}); err != nil {
339			t.Fatal(err)
340		}
341		if err := m2.Close(); err != nil {
342			t.Fatal(err)
343		}
344	
345		// c1 依据不完整（100~300 跳过），c2 依据完整（400 核对）：正常打开。
346		m3, err := Open(path)
347		if err != nil {
348			t.Fatalf("reopen: %v", err)
349		}
350		p, _ := m3.PoseAt(400)
351		if p.X != 9 || p.Y != 9 || p.Variance != 2 {
352			t.Fatalf("PoseAt(400) = %+v, want c2 result (9,9,v2)", p)
353		}
354		m3.Close()
355	
356		// 只属于完整记录 c2 的帧矛盾：其余记录被跳过不影响，整份文件拒绝。
357		tamperFile(t, path, func(fd *fileData) {
358			fd.Trajectory[4].X = 9.5 // t=400 期望 9
359		})
360		assertOpenCorrupt(t, path)
361	}
362	
363	// 兼容规则不得回退到更早记录：帧先被依据完整的 c1 覆盖、后又被含 null
364	// 旧帧的 c2 覆盖时，当前位姿以“最后一次校正 c2”为准但因依据缺失跳过
365	// 比较——不能改用 c1 要求当前位姿回到 c1 的旧结果。
366	func TestOpenNullBasisLastRecordDoesNotFallBackToEarlier(t *testing.T) {
367		path := filepath.Join(t.TempDir(), "m.pose")
368		m, err := Create(path, Config{
369			InitialTime: 0, MaxInterval: 1000, MergeDistance: 10,
370		})
371		if err != nil {
372			t.Fatal(err)
373		}
374		if _, err := m.ImportSegment(Segment{ID: "s1", Frames: []Frame{
375			{Time: 100, DX: 1, MoveVariance: 0.1},
376			{Time: 200, DX: 1, MoveVariance: 0.1},
377		}}); err != nil {
378			t.Fatal(err)
379		}
380		// c1 依据完整，覆盖 100~200。
381		if _, err := m.Correct(Correction{ID: "c1", Anchor: 100,
382			Target: CorrectionTarget{X: 5, Y: 6, Variance: 1}}); err != nil {
383			t.Fatal(err)
384		}
385		// 追加 300 后，c2 覆盖 100~300（此时依据都完整，正常提交）。
386		if _, err := m.ImportSegment(Segment{ID: "s2", Frames: []Frame{
387			{Time: 300, DX: 1, MoveVariance: 0.1},
388		}}); err != nil {
389			t.Fatal(err)
390		}
391		if _, err := m.Correct(Correction{ID: "c2", Anchor: 100,
392			Target: CorrectionTarget{X: 7, Y: 8, Variance: 2}}); err != nil {
393			t.Fatal(err)
394		}
395		if err := m.Close(); err != nil {
396			t.Fatal(err)
397		}
398	
399		// 把 t=300 的依据置空：c2（100~300）依据不完整，成为 100/200/300
400		// 三帧的最后一次覆盖记录。当前 100/200 既不等于 c2 结果也不等于
401		// c1 旧结果，但按兼容规则全部跳过，不回退要求 c1 的值。
402		tamperFile(t, path, func(fd *fileData) {
403			fd.Sources[2] = nil
404			fd.Trajectory[1].X = 500 // t=100
405			fd.Trajectory[2].X = 500 // t=200
406		})
407		m2, err := Open(path)
408		if err != nil {
409			t.Fatalf("must not fall back to earlier fully-based c1: %v", err)
410		}
411		m2.Close()
412	}
